    ('VOCALES DE JUNTAS PARROQUIALES', '1-12-20-18', 'RENOVACIÓN DEMOCRÁTICA', 'ANGOCHAGUA', NULL, 'IMBA LECHON BERENIZ DANIELA', 'BERENIZ IMBA', '5'),
    ('VOCALES DE JUNTAS PARROQUIALES', '1-12-20-18', 'RENOVACIÓN DEMOCRÁTICA', 'ANGOCHAGUA', NULL, 'PAGLLACHO CANCAN KAREN JESSICA', 'KAREN PAGLLACHO', '3'),
    ('VOCALES DE JUNTAS PARROQUIALES', '1-12-20-18', 'RENOVACIÓN DEMOCRÁTICA', 'SAN ANTONIO', NULL, 'HERRERA MORETA JOHN ALEX', 'JOHN HERRERA', '1'),
    ('VOCALES DE JUNTAS PARROQUIALES', '1-12-20-18', 'RENOVACIÓN DEMOCRÁTICA', 'SAN ANTONIO', NULL, 'VILLALBA VENEGAS FELIPE NAPOLEON', 'FELIPE VILLALBA', '5'),
    ('VOCALES DE JUNTAS PARROQUIALES', '1-12-20-18', 'RENOVACIÓN DEMOCRÁTICA', 'SAN ANTONIO', NULL, 'TIXILIMA POTOSI CARLOS MESIAS', 'CARLOS TIXILIMA', '3'),
    ('VOCALES DE JUNTAS PARROQUIALES', '1-12-20-18', 'RENOVACIÓN DEMOCRÁTICA', 'SAN ANTONIO', NULL, 'PANTOJA CABEZAS EVELYN MILENA', 'EVELYN PANTOJA', '4'),
    ('VOCALES DE JUNTAS PARROQUIALES', '1-12-20-18', 'RENOVACIÓN DEMOCRÁTICA', 'SAN ANTONIO', NULL, 'GUAMAN DIAZ JENNIFER NAYELY', 'JENNIFER GUAMAN', '2')
  ) AS d (dignidad, lista, partido, parroquia, distrito, nombre, nombre_papeleta, orden)
  JOIN public.dignidad dig ON dig.descripcion = d.dignidad
  LEFT JOIN public.distrito dis
         ON dis.codigo_canton = '1001' AND dis.dignidad_id = dig.id AND dis.nombre = d.distrito
 WHERE NOT EXISTS (
        SELECT 1 FROM public.candidato c
         WHERE c.canton = 'IBARRA' AND c.dignidad = d.dignidad AND c.lista = d.lista
           AND c.nombre = d.nombre
           AND c.parroquia IS NOT DISTINCT FROM d.parroquia);

-- Cada candidato con distrito debe haber encontrado su distrito
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM public.candidato
                WHERE canton = 'IBARRA' AND dignidad LIKE 'CONCEJALES%' AND distrito_id IS NULL) THEN
        RAISE EXCEPTION 'Hay concejales de Ibarra sin distrito asignado';
    END IF;
END $$;

COMMIT;
